com.mirth.connect.plugins.javascriptstep.script:
var dbConn = null;
var resource_type_id = null;
var globalConfig = null;
var mcoMap = null;
var errorTypeMap = {};
var inputJson,
  rawMessage = connectorMessage.getRawData();
var bundleId = null;
var attributedSource = channelMap.get("attributed_source");
var submittingSource = null;
var mco_id = null;
var mco_screening_id = null;
var mco_details_id = null;
var isSourceValid = false;
var errorTypeMap = {};
var mcoMap = {};
var scrPerferenceMap = null;
var endPoint = null;
var errorDropLocation = null;
// var resourceType=null;

try {
  // connection check
  dbConn = DatabaseConnectionFactory.createDatabaseConnection(
    configurationMap.get("jdbdcDriver"),
    configurationMap.get("jbdcUrl"),
    configurationMap.get("dbName"),
    configurationMap.get("dbPassword")
  );

  // Load configuration and mappings
  try {
    resource_type_id = globalChannelMap.get("bundleResourceTypeId");
    globalConfig = JSON.parse(configurationMap.get("screeningLocation"));
    errorTypeMap = globalChannelMap.get("bundleErrorTypeMap");
    mcoMap = globalChannelMap.get("bundleMcoMap");
    scrPerferenceMap = globalChannelMap.get("scrPerferenceMap");
    endPoint = globalMap.get("screeningEndpoint");
    if (attributedSource) {
      attributedSource = attributedSource.toString().toUpperCase();
    }
    if (globalConfig[attributedSource]) {
      var dropLocationCheck = true;
      if (globalConfig[attributedSource]["bundleOutbound"]) {
        channelMap.put(
          "bundleOutbound",
          globalConfig[attributedSource]["bundleOutbound"]
        );
        dropLocationCheck = false;
      } else {
        dropLocationCheck = true;
      }
      if (globalConfig[attributedSource]["errorFiles"]) {
        errorDropLocation = globalConfig[attributedSource]["errorFiles"];
        channelMap.put("errorFiles", errorDropLocation);
        dropLocationCheck = false;
      }
      if (dropLocationCheck) {
        throw {
          errorType: "VALIDATION_ERROR",
          description: "Invalid attributedSource and not configured",
          rawError: new Error("Invalid attributedSource"),
          stackTrace: new Error().stack,
          msg: inputJson,
        };
      }
    } else {

      throw {
        errorType: "VALIDATION_ERROR",
        description: "Invalid attributedSource and not configured",
        rawError: new Error("Invalid attributedSource"),
        stackTrace: new Error().stack,
        msg: inputJson,
      };

    }
    // resourceType=channelMap.get("resourceType");
  } catch (configErr) {
    throw {
      errorType: "CONFIG_RETERIVAL_ERROR",
      description: "Failed to retrieve or parse configuration",
      rawError: configErr,
      stackTrace: configErr.stack,
      msg: inputJson,
    };
  }

  try {
    inputJson = JSON.parse(rawMessage);
    if (inputJson.hasOwnProperty("medicaid_cin")) {
      delete inputJson["medicaid_cin"];
    }
    rawMessage = JSON.stringify(inputJson);
    logger.info("rawMessage" + rawMessage);
  } catch (err) {
    throw {
      errorType: "PARSE_ERRROR",
      description: "Unable to Parse Notification Message",
      rawError: err,
      stackTrace: err.stack,
      rawMessage: rawMessage,
    };
  }

  // Parse incoming message
  try {
    if (!(inputJson && inputJson.bundle_id)) {
      throw {
        errorType: "VALIDATION_ERROR",
        description: "Missing bundleId.",
        rawError: new Error("bundleId is missing."),
        stackTrace: new Error().stack,
        msg: inputJson,
      };
    } else {
      bundleId = inputJson.bundle_id;
      channelMap.put("bundle_id", bundleId);
    }
    if (!(inputJson && inputJson.attributed_source)) {
      throw {
        errorType: "VALIDATION_ERROR",
        description: "Missing attributed_source.",
        rawError: new Error("attributed_source is missing."),
        stackTrace: new Error().stack,
        msg: inputJson,
      };
    } else {
      attributedSource = inputJson.attributed_source.toString().toUpperCase();
      channelMap.put("attributed_source", attributedSource);
    }
    var now = new Date();
    var yyyy = now.getFullYear();
    var mm = String(now.getMonth() + 1).padStart(2, '0');
    var dd = String(now.getDate()).padStart(2, '0');
    var yyyymmdd = yyyy + mm + dd;

    // channelMap.put("fileName",attributedSource + "_hrsnob_"+resourceType+"_" +yyyymmdd+"_"+ bundleId + ".json" );
    channelMap.put("fileName", attributedSource + "_hrsnob_" + yyyymmdd + "_" + bundleId + ".json");
    if (!(inputJson && inputJson.submitting_source)) {
      throw {
        errorType: "VALIDATION_ERROR",
        description: "Missing submitting_source.",
        rawError: new Error("submitting_source is missing."),
        stackTrace: new Error().stack,
        msg: inputJson,
      };
    } else {
      submittingSource = inputJson.submitting_source.toString().toUpperCase()
      channelMap.put("submitting_source", submittingSource)
    }

    channelMap.put(
      "fhirQuery",
      endPoint + "bundle_id=" + bundleId + "&source_code=" + submittingSource
    );
    logger.info(channelMap.get("fhirQuery"));

  } catch (jsonErr) {
    throw {
      errorType: "VALIDATION_ERROR",
      description: "Invalid Missing bundleId or attributedSource or submittingSource",
      rawError: new Error("bundleId or attributedSource or submittingSource is missing/invalid"),
      stackTrace: new Error().stack,
      msg: inputJson,
    };
  }

  logger.info("MCO_ID" + attributedSource + "" + mcoMap[attributedSource]);
  if (mcoMap[attributedSource]) {
    mco_id = mcoMap[attributedSource];
  }
  logger.info(mco_id);
  if (!mcoMap[attributedSource]) {
    throw {
      errorType: "VALIDATION_ERROR",
      description: "Invalid attributedSource not found in prefence List",
      rawError: new Error("Invalid attributedSource"),
      stackTrace: new Error().stack,
      msg: inputJson,
    };
  }

  logger.info("fetching Latest Query");
  var fetchScreeningIdsQuery =
    "SELECT mco_screening_id FROM screening_extracts.mco_screening_extracts WHERE request_bundle_id = ? and mco_id =? and is_active ='1' ORDER BY mco_screening_id DESC LIMIT 1";
  var rs = dbConn.executeCachedQuery(fetchScreeningIdsQuery, [bundleId, mco_id]);

  var latestScreeningId = null;
  while (rs.next()) {
    latestScreeningId = rs.getLong("mco_screening_id");
  }

  if (latestScreeningId != null) {
    var updateExtractsQuery =
      "UPDATE screening_extracts.mco_screening_extracts SET is_active = '0' WHERE mco_screening_id = ? ";
    dbConn.executeUpdate(updateExtractsQuery, [latestScreeningId]);

    var updateDetailsQuery =
      "UPDATE screening_extracts.mco_screening_extracts_details SET is_active = '0' WHERE mco_screening_id = ?";
    dbConn.executeUpdate(updateDetailsQuery, [latestScreeningId]);

    var updateErrorsQuery =
      "UPDATE screening_extracts.mco_screening_extracts_error_logs SET is_active = '0' WHERE mco_screening_id = ?";
    dbConn.executeUpdate(updateErrorsQuery, [latestScreeningId]);

    logger.info(
      "Deactivated all previous records for bundleId: " +
      bundleId +
      " with screeningId: " +
      latestScreeningId
    );
  } else {
    logger.info(
      "No existing records found for bundleId: " +
      bundleId +
      ". Proceeding to insert fresh."
    );
  }

  // Save screening extract and details
  var rs3 = dbConn.executeCachedQuery(
    "INSERT INTO screening_extracts.mco_screening_extracts (mco_id, resource_type_id, status, request_bundle_id, created_on_utc, updated_on_utc, acknowledge_time,is_active) VALUES (?, ?, ?, ?, now(), now(), now(),'1') RETURNING mco_screening_id",
    [mco_id, resource_type_id, "RECEIVED", bundleId]
  );
  if (rs3.next()) mco_screening_id = rs3.getLong(1);
  channelMap.put("mco_screening_id", mco_screening_id);

  var rs4 = dbConn.executeCachedQuery(
    "INSERT INTO screening_extracts.mco_screening_extracts_details (mco_screening_id, notification_doc, resource_type_id, status, is_active, created_on_utc,updated_on_utc) VALUES (?, ?::json, ?, ?, '1', now(),now()) RETURNING mco_screening_extracts_details_id",
    [mco_screening_id, JSON.stringify(inputJson), resource_type_id, "RECEIVED"]
  );
  if (rs4.next()) mco_details_id = rs4.getLong(1);
  channelMap.put("mco_screening_extracts_details_id", mco_details_id);
  logger.info("Source Transformer Completed");
} catch (e) {
  // Fallback connection for logging, if not already connected
  if (
    !dbConn ||
    (e.javaClassName && e.javaClassName.toString().includes("PSQLException")) ||
    (e.description && e.description.toString().includes("connect"))
  ) {
    var pgError = {
      errorType: "POSTGRES_ERROR",
      description: "Unable to connect to database",
      rawError: e,
      stackTrace: e.stack || new Error().stack,
      msg: rawMessage,
    };

    logger.error("ERROR TYPE: " + pgError.errorType);
    logger.error("DESCRIPTION: " + pgError.description);
    logger.error("STACK TRACE: " + pgError.stackTrace);
    throw "ERROR OCCURRED: " + pgError.errorType;
  }
  try {
    if (!dbConn) {
      dbConn = DatabaseConnectionFactory.createDatabaseConnection(
        configurationMap.get("jdbdcDriver"),
        configurationMap.get("jbdcUrl"),
        configurationMap.get("dbName"),
        configurationMap.get("dbPassword")
      );
    }

    var fallbackErrJson = {
      errorType: e.errorType,
      description: e.description,
      stack: e.stackTrace,
      msg: e.msg ? e.msg : {},
      rawError: e.rawError,
    };

    if (e.rawMessage) fallbackErrJson["rawMessage"] = e.rawMessage;
    logger.info("fallbackErrJson" + JSON.stringify(fallbackErrJson));
    if (mco_screening_id == null) {
      var rs1 = dbConn.executeCachedQuery(
        "INSERT INTO screening_extracts.mco_screening_extracts (mco_id, resource_type_id, status, request_bundle_id, created_on_utc,updated_on_utc, acknowledge_time,is_active) VALUES (?, ?, ?, ?, now(),now(), now(),'1') RETURNING mco_screening_id",
        [mco_id, resource_type_id, "ERROR", bundleId]
      );
      if (rs1.next()) mco_screening_id = rs1.getLong(1);
      logger.info(mco_screening_id);
    } else {
      var rs1 = dbConn.executeCachedQuery(
        "UPDATE screening_extracts.mco_screening_extracts SET status= 'ERROR', updated_on_utc =now() where mco_screening_id =?",
        [mco_screening_id]
      );
    }
    if (!inputJson) {
      inputJson = { rawMessage: e.rawMessage };
    }
    var rs2 = dbConn.executeCachedQuery(
      "INSERT INTO screening_extracts.mco_screening_extracts_details (mco_screening_id, notification_doc, resource_type_id, status, is_active, created_on_utc, updated_on_utc) VALUES (?, ?::json, ?, ?, '1', now(),now()) RETURNING mco_screening_extracts_details_id",
      [mco_screening_id, JSON.stringify(inputJson), resource_type_id, "ERROR"]
    );
    if (rs2.next()) mco_details_id = rs2.getLong(1);
    logger.info(rs2.getLong(1));
    dbConn.executeUpdate(
      "INSERT INTO screening_extracts.mco_screening_extracts_error_logs (mco_screening_id, mco_screening_extracts_details_id, error_json, created_on_utc, updated_on_utc,is_active, screening_error_type_id) VALUES (?, ?, ?::json, now(),now() ,'1', ?)",
      [
        mco_screening_id,
        mco_details_id,
        JSON.stringify(fallbackErrJson),
        errorTypeMap && errorTypeMap[e.errorType],
      ]
    );
    var fileName = channelMap.get("fileName");
    if (bundleId == null) {
      var now = new Date();
      var yyyy = now.getFullYear();
      var mm = String(now.getMonth() + 1).padStart(2, '0');
      var dd = String(now.getDate()).padStart(2, '0');
      var hh = String(now.getHours()).padStart(2, '0');
      var min = String(now.getMinutes()).padStart(2, '0');
      var ss = String(now.getSeconds()).padStart(2, '0');
      var yyyymmddhhmmss = yyyy + mm + dd + hh + min + ss;
      channelMap.put("fileName", "Error_" + attributedSource + "_hrsnob_" + yyyymmddhhmmss + ".json");
    } else {
      channelMap.put("fileName", "Error_" + fileName);
    }
    channelMap.put("isSourceValidationError", true);
    channelMap.put("sftpDropLocation", errorDropLocation);
    channelMap.put("fileContent", JSON.stringify(fallbackErrJson));


  } catch (fallbackErr) {
    logger.error("Failed to log fallback error: " + fallbackErr);
  } finally {
    if (dbConn) {
      try {
        dbConn.close();
      } catch (closeErr) {
        logger.warn("DB close failed: " + closeErr);
      }
    }
  }

  logger.error("ERROR TYPE: " + e.errorType);
  logger.error("DESCRIPTION: " + e.description);
  logger.error("STACK TRACE: " + e.stackTrace);
  //  throw "ERROR OCCURED" + e.errorType;
} finally {
  if (dbConn) {
    try {
      dbConn.close();
    } catch (closeErr) {
      logger.warn("DB close failed: " + closeErr);
    }
  }
}

com.mirth.connect.plugins.javascriptrule.script:
var requestUri = String($('requestUri') || '');

logger.info("Request URI: " + requestUri);

if (requestUri == "/healthcheck") {
    return true;
}


var dbConn = null;
var resource_type_id = null;
var globalConfig = {}, errorTypeMap = {}, mcoMap = {}, scrPerferenceMap = {};
var inputJson, rawMessage = connectorMessage.getRawData();
var bundleId = null;
var attributeSource = null;
var mco_id = null;
var mco_screening_id = null;
var mco_details_id = null;


try {
  dbConn = DatabaseConnectionFactory.createDatabaseConnection(
    configurationMap.get("jdbdcDriver"),
    configurationMap.get("jbdcUrl"),
    configurationMap.get("dbName"),
    configurationMap.get("dbPassword")
  );

  try {
    resource_type_id = globalChannelMap.get("bundleResourceTypeId");
    logger.info(resource_type_id);
    errorTypeMap = globalChannelMap.get("bundleErrorTypeMap");
    mcoMap = globalChannelMap.get("bundleMcoMap");
    scrPerferenceMap = globalChannelMap.get("scrPerferenceMap");
  } catch (configErr) {
    logger.info("Config retrieval error");
    throw {
      errorType: "CONFIG_RETERIVAL_ERROR",
      description: "Failed to retrieve or parse configuration",
      rawError: configErr,
      stackTrace: configErr.stack,
      msg: inputJson,
    };
  }
  try {
    inputJson = JSON.parse(rawMessage);
    if (inputJson.hasOwnProperty("medicaid_cin")) {
      delete inputJson["medicaid_cin"];
    }
    /*
    if (!inputJson || !inputJson.bundle_type_list || !Array.isArray(inputJson.bundle_type_list)|| (Array.isArray(inputJson.bundle_type_list) && inputJson.bundle_type_list.length==0)) {
      throw {
        errorType: "VALIDATION_ERROR",
        description: "Missing Bundle Type List",
        rawError: new Error("Missing Bundle Type List"),
        stackTrace: new Error().stack,
        msg: inputJson,
      };
    }

  var resourceType = inputJson.bundle_type_list[0].toString().toLowerCase();

  if (resourceType !== "screening" &&  resourceType !== "assessment" &&  resourceType !== "referral") {
    throw {
      errorType: "VALIDATION_ERROR",
      description: "Invalid Bundle Type: " + resourceType,
      rawError: new Error("Invalid Bundle Type: " + resourceType),
      stackTrace: new Error().stack,
      msg: inputJson,
    };
  }
        channelMap.put("resourceType", resourceType);
    */

    if (inputJson["attributed_source"] && scrPerferenceMap[inputJson["attributed_source"].toString().toUpperCase()]) {
      channelMap.put("attributed_source", inputJson["attributed_source"]);
      return true;
    }
    if (inputJson.bundle_id) {
      bundleId = inputJson.bundle_id;
    }
    if (inputJson.attributed_source) {
      attributeSource = inputJson.attributed_source.toString().toUpperCase();
      if (mcoMap[attributeSource]) {
        mco_id = mcoMap[attributeSource];
      }
    }
    rawMessage = JSON.stringify(inputJson);
  } catch (err) {
    var errorMessage;
    var description;
    logger.info("Inside Error:" + err.errorType + " " + err.description);
    if (err && err.errorType == 'VALIDATION_ERROR') {
      errorMessage = err.errorType;
      description = err.description;
    } else {
      errorMessage = "PARSE_ERROR";
      description = "Unable to Parse Notification Message";
    }
    throw {
      errorType: errorMessage,
      description: description,
      rawError: err,
      stackTrace: err.stack,
      rawMessage: rawMessage,
    };
  }

  var rs1 = dbConn.executeCachedQuery(
    "INSERT INTO screening_extracts.mco_screening_extracts (mco_id, resource_type_id, status, request_bundle_id, created_on_utc,updated_on_utc, acknowledge_time,is_active) VALUES (?, ?, ?, ?, now(),now(), now(),'1') RETURNING mco_screening_id",
    [mco_id, resource_type_id, "FILTERED", bundleId]
  );
  if (rs1.next()) mco_screening_id = rs1.getLong(1);

  var rs2 = dbConn.executeCachedQuery(
    "INSERT INTO screening_extracts.mco_screening_extracts_details (mco_screening_id, notification_doc, resource_type_id, status, is_active, created_on_utc, updated_on_utc) VALUES (?, ?::json, ?, ?, '1', now(),now()) RETURNING mco_screening_extracts_details_id",
    [mco_screening_id, JSON.stringify(inputJson), resource_type_id, "FILTERED"]
  );
  if (rs2.next()) mco_details_id = rs2.getLong(1);
  logger.info(rs2.getLong(1));
  return false;

} catch (e) {
  if (
    !dbConn ||
    (e.javaClassName && e.javaClassName.toString().includes("PSQLException")) ||
    (e.description && e.description.toString().includes("connect"))
  ) {
    var pgError = {
      errorType: "POSTGRES_ERROR",
      description: "Unable to connect to database",
      rawError: e,
      stackTrace: e.stack || new Error().stack,
      msg: rawMessage,
    };

    logger.error("ERROR TYPE: " + pgError.errorType);
    logger.error("DESCRIPTION: " + pgError.description);
    logger.error("STACK TRACE: " + pgError.stackTrace);
    throw "ERROR OCCURRED: " + pgError.errorType;
  }
  try {

    var fallbackErrJson = {
      errorType: e.errorType,
      description: e.description,
      stack: e.stackTrace,
      msg: e.msg ? e.msg : {},
      rawError: e.rawError,
    }; if (!inputJson) {
      inputJson = { rawMessage: e.rawMessage };
    }
    var rs1 = dbConn.executeCachedQuery(
      "INSERT INTO screening_extracts.mco_screening_extracts (mco_id, resource_type_id, status, request_bundle_id, created_on_utc,updated_on_utc, acknowledge_time,is_active) VALUES (?, ?, ?, ?, now(),now(), now(),'1') RETURNING mco_screening_id",
      [mco_id, resource_type_id, "ERROR", bundleId]
    );
    if (rs1.next()) mco_screening_id = rs1.getLong(1);
    logger.info(mco_screening_id);
    var rs2 = dbConn.executeCachedQuery(
      "INSERT INTO screening_extracts.mco_screening_extracts_details (mco_screening_id, notification_doc, resource_type_id, status, is_active, created_on_utc, updated_on_utc) VALUES (?, ?::json, ?, ?, '1', now(),now()) RETURNING mco_screening_extracts_details_id",
      [mco_screening_id, JSON.stringify(inputJson), resource_type_id, "ERROR"]
    );
    if (rs2.next()) mco_details_id = rs2.getLong(1);
    logger.info(rs2.getLong(1));
    dbConn.executeUpdate(
      "INSERT INTO screening_extracts.mco_screening_extracts_error_logs (mco_screening_id, mco_screening_extracts_details_id, error_json, created_on_utc, updated_on_utc,is_active, screening_error_type_id) VALUES (?, ?, ?::json, now(),now() ,'1', ?)",
      [
        mco_screening_id,
        mco_details_id,
        JSON.stringify(fallbackErrJson),
        errorTypeMap && errorTypeMap[e.errorType],
      ]
    );
  } catch (fallbackErr) {
    logger.error("Failed to log fallback error: " + fallbackErr);
    throw fallbackErr;
  } finally {
    if (dbConn) {
      try {
        dbConn.close();
      } catch (closeErr) {
        logger.warn("DB close failed: " + closeErr);
      }
    }
  }

  logger.error("ERROR TYPE: " + e.errorType);
  logger.error("DESCRIPTION: " + e.description);
  logger.error("STACK TRACE: " + e.stackTrace);
  throw "ERROR OCCURED" + e.errorType;
} finally {
  if (dbConn) {
    try {
      dbConn.close();
    } catch (closeErr) {
      logger.warn("DB close failed: " + closeErr);
    }
  }

}

com.mirth.connect.plugins.javascriptstep.script:
var dbConn = null;
var bundleResponseStatus = response.getNewMessageStatus();
var responseBody = response.getMessage();
var errorText = response.getError();
var statusMessage = response.getStatusMessage();
channelMap.put("bundleResponseStatus", bundleResponseStatus);


var mco_screening_id = channelMap.get("mco_screening_id");
var mco_details_id = channelMap.get("mco_screening_extracts_details_id");
var resource_type_id = globalChannelMap.get("bundleResourceTypeId");
var errorTypeMap =globalChannelMap.get("bundleErrorTypeMap");
var request_bundle_id = channelMap.get("bundleId");
var responseBundleId = null;
var sftpDropLocation=null;

try {
  dbConn = DatabaseConnectionFactory.createDatabaseConnection(
    configurationMap.get("jdbdcDriver"),
    configurationMap.get("jbdcUrl"),
    configurationMap.get("dbName"),
    configurationMap.get("dbPassword")
  );

  logger.info("bundleResponseStatus " + bundleResponseStatus.toString());
  if (bundleResponseStatus.toString() != "ERROR" && responseBody) {
    var parsed = null;

    try {
      parsed = JSON.parse(responseBody);
    } catch (parseErr) {
    		channelMap.put("errorResponseBody", responseBody);
    		channelMap.put("fileContent", responseBody);
      throw {
        errorType: "PARSE_ERRROR",
        description: "Unable to parse response JSON from API",
        rawError: parseErr,
        stackTrace: parseErr.stack
      };
    }

    responseBundleId = parsed.bundle_id || parsed.id || null;
    if (responseBundleId) {
      channelMap.put("response_bundle_id", responseBundleId);
      if (mco_screening_id) {
        dbConn.executeUpdate(
          "UPDATE screening_extracts.mco_screening_extracts SET response_bundle_id = ?, status = ?, updated_on_utc = now()  WHERE mco_screening_id = ?",
          [responseBundleId, "INPROGRESS", mco_screening_id]
        );
      }
      if (mco_details_id) {
        dbConn.executeUpdate(
          "UPDATE screening_extracts.mco_screening_extracts_details   SET status = ?, updated_on_utc = now()  WHERE mco_screening_extracts_details_id = ?",
          ["INPROGRESS", mco_details_id]
        );
      }

      logger.info(
        "Updated status to INPROGRESS for response_bundle_id: " +
          responseBundleId
      );
    } else {
      logger.warn("No response_bundle_id found in API response.");
    }
    channelMap.put("fileContent", responseBody);
    channelMap.put("sftpDropLocation",  $("bundleOutbound"));
  } else {
      logger.info("API_ERROR");
      channelMap.put("sftpDropLocation",  $("errorFiles"));
      if(responseBody==null || responseBody==""){
      	responseBody="EMPTY DATALAKE API RESPONSE";
      }
      channelMap.put("fileContent", responseBody);
    	channelMap.put("errorResponseBody", responseBody);
    	channelMap.put("sftpDropLocation",  $("errorFiles"));

    throw {
      errorType: "API_ERROR",
      description: "API responded with ERROR",
      rawError: new Error(errorText || "Unknown API error"),
      stackTrace: new Error().stack,
      statusMessage: statusMessage,
      errorResponseBody:responseBody
    };
  }
} catch (e) {	
  var fileName= channelMap.get("fileName");
  channelMap.put("fileName", "Error_"+fileName);
  channelMap.put("sftpDropLocation",  $("errorFiles"));
  logger.info("HTTP sender catch ");
  if (
    !dbConn ||
    (e.javaClassName && e.javaClassName.toString().includes("PSQLException")) ||
    (e.description && e.description.toString().includes("connect"))
  ) {
    var pgError = {
      errorType: "POSTGRES_ERROR",
      description: "Unable to connect to database",
      rawError: e,
      stackTrace: e.stack || new Error().stack,
      msg: rawMessage,
    };

    logger.error("ERROR TYPE: " + pgError.errorType);
    logger.error("DESCRIPTION: " + pgError.description);
    logger.error("STACK TRACE: " + pgError.stackTrace);
    throw "ERROR OCCURRED: " + pgError.errorType;
  }
  logger.info("eror types"+errorTypeMap);
  logger.info("Error Type"+e.errorType);
	logger.info("logger error Type"+ errorTypeMap[e.errorType]);
  try {
    if (!dbConn) {
      dbConn = DatabaseConnectionFactory.createDatabaseConnection(
        configurationMap.get("jdbdcDriver"),
        configurationMap.get("jbdcUrl"),
        configurationMap.get("dbName"),
        configurationMap.get("dbPassword")
      );
    }
    logger.info(e.errorType);
    logger.info(e.errorType=='API_ERROR');

    var fallbackErrJson = {
      errorType: e.errorType,
      description: e.description || e.toString(),
      stack: e.stackTrace || new Error().stack,
      statusMessage: e.statusMessage || statusMessage,
      rawError: e.rawError || e,
    };
    if (mco_screening_id) {
      dbConn.executeUpdate(
        "UPDATE screening_extracts.mco_screening_extracts SET response_bundle_id = ?, status = ?, updated_on_utc = now()  WHERE mco_screening_id = ?",
        [responseBundleId, "ERROR", mco_screening_id]
      );
    }
    if (mco_details_id) {
      dbConn.executeUpdate(
        "UPDATE screening_extracts.mco_screening_extracts_details SET status = ?, updated_on_utc = now() WHERE mco_screening_extracts_details_id = ?",
        ["ERROR", mco_details_id]
      );
    }


    dbConn.executeUpdate(
      "INSERT INTO screening_extracts.mco_screening_extracts_error_logs (mco_screening_id, mco_screening_extracts_details_id, error_json, created_on_utc,updated_on_utc, is_active, screening_error_type_id) VALUES (?, ?, ?::json, now(), now(), '1', ?)",
      [
        mco_screening_id,
        mco_details_id,
        JSON.stringify(fallbackErrJson),
        errorTypeMap && errorTypeMap[e.errorType],
      ]
    );

    logger.error(
      "Updated status to ERROR for mco_screening_id: " + mco_screening_id
    );
  } catch (fallbackErr) {
    logger.error("fallback DB logging failed: " + fallbackErr);
  }finally {
    if (dbConn) {
      try {
        dbConn.close();
      } catch (closeErr) {
        logger.warn("DB close failed: " + closeErr);
      }
    }
  }
  logger.error("ERROR TYPE: " + e.errorType);
  logger.error("DESCRIPTION: " + e.description);
  logger.error("STACK TRACE: " + e.stackTrace);
  throw "ERROR OCCURED: " + (e.errorType || "UNKNOWN");
} finally {
  if (dbConn) {
    try {
      dbConn.close();
    } catch (closeErr) {
      logger.warn("DB connection close failed: " + closeErr);
    }
  }
}

var dbConn = null;
var sftpResponseStatus = response.getNewMessageStatus();
var errorText = response.getError();
var statusMessage = response.getStatusMessage();
var responseBody = response.getMessage();
var mco_screening_id = channelMap.get("mco_screening_id");
var mco_details_id = channelMap.get("mco_screening_extracts_details_id");
var errorTypeMap = globalChannelMap.get("bundleErrorTypeMap");
var File = Packages.java.io.File;
function verifyFileResponse(filePath) {
  var file = new File(filePath);
  if (file.exists()) {
    logger.info("Confirmed: File exists at " + filePath);
    return true;
  } else {
    logger.error("File not found at " + filePath);
    return false;
  }
}

try {
  dbConn = DatabaseConnectionFactory.createDatabaseConnection(
    configurationMap.get("jdbdcDriver"),
    configurationMap.get("jbdcUrl"),
    configurationMap.get("dbName"),
    configurationMap.get("dbPassword")
  );

  logger.info("STATAUS " + sftpResponseStatus.toString());

  if (!$('isSourceValidationError') && $('bundleResponseStatus') != "ERROR" && sftpResponseStatus!="ERROR" && verifyFileResponse($('sftpDropLocation') + "/" + $('fileName'))) {
      if (mco_screening_id) {
        dbConn.executeUpdate(
          "UPDATE screening_extracts.mco_screening_extracts SET status = ?,sent_file_name=?, updated_on_utc = now(), sent_to_mco=now() WHERE mco_screening_id = ?",
          ["COMPLETED", $("fileName"), mco_screening_id]
        );
      }
      if (mco_details_id) {
        dbConn.executeUpdate(
          "UPDATE screening_extracts.mco_screening_extracts_details SET status = ?, updated_on_utc = now() WHERE mco_screening_extracts_details_id = ?",
          ["COMPLETED", mco_details_id]
        );
      }
  } else {
    if (sftpResponseStatus == 'ERROR' || !verifyFileResponse($('sftpDropLocation') + "/" + $('fileName'))) {
      throw {
        errorType: "SFTP_ERROR",
        description: "SFTP ERROR ERROR",
        rawError: new Error(errorText || "Unknown ERROR error"),
        stackTrace: new Error().stack,
        statusMessage: statusMessage,
        errorResponseBody: responseBody
      };
    }
  }


} catch (e) {
  logger.info("sftp catch ");
  if (
    !dbConn ||
    (e.javaClassName && e.javaClassName.toString().includes("PSQLException")) ||
    (e.description && e.description.toString().includes("connect"))
  ) {
    var pgError = {
      errorType: "POSTGRES_ERROR",
      description: "Unable to connect to database",
      rawError: e,
      stackTrace: e.stack || new Error().stack,
    };

    logger.error("ERROR TYPE: " + pgError.errorType);
    logger.error("DESCRIPTION: " + pgError.description);
    logger.error("STACK TRACE: " + pgError.stackTrace);
    throw "ERROR OCCURRED: " + pgError.errorType;
  }
  logger.error(
    "SFTP or DB error: " + (e.errorType || "UNKNOWN") + " - " + e.description
  );

  // Reconnect DB if needed
  if (!dbConn) {
    try {
      dbConn = DatabaseConnectionFactory.createDatabaseConnection(
        configurationMap.get("jdbdcDriver"),
        configurationMap.get("jbdcUrl"),
        configurationMap.get("dbName"),
        configurationMap.get("dbPassword")
      );
    } catch (fallbackErr) {
      logger.error("Unable to reconnect to DB to log error: " + fallbackErr);
      throw "POSTGRES_ERROR";
    }
  }

  try {
    var errorJson = {
      errorType: e.errorType || "SFTP_ERROR",
      description: e.description || e.toString(),
      stackTrace: e.stackTrace || (e.rawError && e.rawError.stack) || "",
      file: fileName
    };
    if (mco_screening_id) {
      dbConn.executeUpdate(
        "UPDATE screening_extracts.mco_screening_extracts SET status = ?, updated_on_utc = now() WHERE mco_screening_id = ?",
        ["ERROR", mco_screening_id]
      );
    }
    if (mco_details_id) {
      dbConn.executeUpdate(
        "UPDATE screening_extracts.mco_screening_extracts_details SET status = ?, updated_on_utc = now() WHERE mco_screening_extracts_details_id = ?",
        ["ERROR", mco_details_id]
      );
    }
    dbConn.executeUpdate(
      "INSERT INTO screening_extracts.mco_screening_extracts_error_logs (mco_screening_id, mco_screening_extracts_details_id, error_json, created_on_utc,updated_on_utc, is_active, screening_error_type_id) VALUES (?, ?, ?::json, now(), now(), '1', ?)",
      [
        mco_screening_id,
        mco_details_id,
        JSON.stringify(errorJson),
        errorTypeMap["SFTP_ERROR"],
      ]
    );
  } catch (logErr) {
    logger.error("Failed to log error to DB: " + logErr);
    throw "POSTGRES_ERROR";
  } finally {
    try {
      if (dbConn) dbConn.close();
    } catch (closeErr) {
      logger.warn("Failed to close DB connection: " + closeErr);
    }
  }

  throw (
    "SFTP Upload or Status Update Failure: " + (e.errorType || "SFTP_ERROR")
  );
} finally {
  try {
    if (dbConn) dbConn.close();
  } catch (closeErr) {
    logger.warn("Failed to close DB connection: " + closeErr);
  }
}

channel.postprocessingScript:
// This script executes once after a message has been processed
// Responses returned from here will be stored as "Postprocessor" in the response map
return;

channel.deployScript:
// This script executes once when the channel is deployed
// You only have access to the globalMap and globalChannelMap here to persist data
logger.info("started");
var dbConn;
try {
  var errorTypeMap = {},resource_type_id,mcoMap = {},scrPerferenceMap={};
  dbConn = DatabaseConnectionFactory.createDatabaseConnection(
    configurationMap.get("jdbdcDriver"),
    configurationMap.get("jbdcUrl"),
    configurationMap.get("dbName"),
    configurationMap.get("dbPassword")
  );
  var rsErr = dbConn.executeCachedQuery(
    "SELECT screening_error_type_name, screening_error_type_id FROM screening_extracts.screening_error_types WHERE is_active = '1'"
  );
  while (rsErr.next()) {
    var ename = rsErr.getString("screening_error_type_name");
    var id = rsErr.getLong("screening_error_type_id");
    if (ename && id) {
      errorTypeMap[ename] = id;
    }
  }
  logger.info(JSON.stringify(errorTypeMap));
  globalChannelMap.put("bundleErrorTypeMap", errorTypeMap);

  var rsRes = dbConn.executeCachedQuery(
    "SELECT resource_type_id FROM screening_extracts.resource_types WHERE resource_type_name = 'BUNDLE' AND is_active = '1'"
  );
  if (rsRes.next()) {
    resource_type_id = rsRes.getInt("resource_type_id");
  }
  logger.info("ResourceID : " + resource_type_id);
  globalChannelMap.put("bundleResourceTypeId", resource_type_id);
  var rsMco = dbConn.executeCachedQuery(
    "SELECT tenant_id, tenant_name,tenant_short_code FROM techbd_udi_ingress.tenants WHERE is_active = '1'"
  );
  while (rsMco.next()) {
    var mcoCode = rsMco.getString("tenant_short_code");
    var mcoId = rsMco.getString("tenant_id");
    if (mcoCode && mcoId) {
      mcoMap[mcoCode] = mcoId;
    }
  }
  logger.info("mcoMap" + JSON.stringify(mcoMap));
  globalChannelMap.put("bundleMcoMap", mcoMap);
  logger.info("Initial Config Completed");

  var pfMco = dbConn.executeCachedQuery( "SELECT msp.tenant_id as tenant_id , m.tenant_short_code as tenant_short_code FROM screening_extracts.mco_screening_preferences msp inner join techbd_udi_ingress.tenants m on msp.tenant_id =m.tenant_id inner join screening_extracts.resource_types rt on msp.resource_type_id  = rt.resource_type_id WHERE msp.is_active = '1' and m.is_active ='1'and UPPER(rt.resource_type_name)='BUNDLE'");
  while (pfMco.next()) {  scrPerferenceMap[pfMco.getString("tenant_short_code")] = pfMco.getString("tenant_id");}
  logger.info("Preference Map" + JSON.stringify(scrPerferenceMap));
  globalChannelMap.put("scrPerferenceMap", scrPerferenceMap);

} catch (e) {
  logger.error("Error initializing globalChannelMap values: " + e);
} finally {	
	if(dbConn){
       dbConn.close();
	}
}

return;

channel.undeployScript:
// This script executes once when the channel is undeployed
// You only have access to the globalMap and globalChannelMap here to persist data
return;

