                var fname = fileNames[file]['fileName']
                var fileResults = dbConn.executeCachedQuery(
                    "UPDATE screening_extracts.mco_screening_extracts_details SET status ='VALIDATED',updated_on_utc=NOW() WHERE file_name=? and is_active ='1' returning *",
                    [fname]
                );
            }
            var fileResult = dbConn.executeCachedQuery(
                "UPDATE screening_extracts.mco_screening_extracts SET status ='VALIDATED',updated_on_utc=NOW() WHERE control_file_name=? and is_active ='1'  returning *",
                [originalFileName]
            );
            logger.info("All files have been successfully validated.");
        }
        catch (err) {
            throw {
                errorType: "POSTGRES ERROR",
                description: "Unable to connect to db",
                rawError: err,
                stackTrace: err.stack,
                msg: err.message
            };
        }

        channelMap.put("sentToMco", allFilesValid)
    } else {
        try {
            if (!dbConn) {
                dbConn = DatabaseConnectionFactory.createDatabaseConnection(
                    jdbdcDriver,
                    jbdcUrl,
                    dbName,
                    dbPassword
                );

            }
            for (var file = 0; file < fileNames.length; file++) {
                var fname = fileNames[file]['fileName']
                var fileResults = dbConn.executeCachedQuery(
                    "UPDATE screening_extracts.mco_screening_extracts_details SET status ='ERROR',updated_on_utc =NOW() WHERE file_name=? and is_active ='1' returning *",
                    [fname]
                );
            }
            var fileResult = dbConn.executeCachedQuery(
                "UPDATE screening_extracts.mco_screening_extracts SET status ='ERROR',updated_on_utc=NOW() WHERE control_file_name=? and is_active ='1' returning *",
                [originalFileName]
            );
            logger.info("All files have been successfully validated.");
        }
        catch (err) {
            throw {
                errorType: "POSTGRES ERROR",
                description: "Unable to connect to db",
                rawError: err,
                stackTrace: err.stack,
                msg: err.message
            };
        }

        channelMap.put("sentToMco", allFilesValid)
    }


    // Set the global validated status in globalChannelMap
    globalChannelMap.put("validated", allFilesValid);
    globalChannelMap.put("error", errorsToAppend);
    globalChannelMap.put("fileNames", fileNames);

    // Disconnect from SFTP after all files have been processed

}
catch (err) {
    logger.info("error in inserting db" + err)
    try {
        if (!dbConn) {
            dbConn = DatabaseConnectionFactory.createDatabaseConnection(
                jdbdcDriver,
                jbdcUrl,
                dbName,
                dbPassword
            );
        }
        var error_type_id = errorTypeMap["MIRTH_INTERNAL_ERROR"]
        var screening_id = channelMap.get("screeningId");
        var fallbackErrJson = {
            errorType: err.errorType ? err.errorType : "SFTP ERROR",
            description: "Error While copy or moving" + file + "to" + path,
            stack: err.stack,
            msg: err.msg ? err.msg : err.message,
            rawError: err.rawError ? err.rawError : "SFTP ERROR",
        };
        var fileResult = dbConn.executeCachedQuery(
            "INSERT INTO screening_extracts.mco_screening_extracts_error_logs(mco_screening_id,mco_screening_extracts_details_id,error_json, created_on_utc, updated_on_utc, is_active, screening_error_type_id) VALUES (?,?,?::json, NOW(),NOW(),'1',?) returning *",
            [screening_id,
                screeningDetailsId,
                JSON.stringify(fallbackErrJson),
                error_type_id]

        );

    }
    catch (err) {
        throw {
            errorType: "POSTGRES ERROR",
            description: "Unable to connect to db",
            rawError: err,
            stackTrace: err.stack,
            msg: err.message
        };
    }
    logger.info(err)
    throw err;
} finally {
    if (dbConn) {
        dbConn.close();
    }
}

properties.script:
try {
	var jdbdcDriver = configurationMap.get("jdbdcDriver");
	var jbdcUrl = configurationMap.get("jbdcUrl");
	var dbName = configurationMap.get("dbName");
	var dbPassword = configurationMap.get("dbPassword");
	var screeningPath = configurationMap.get("screeningLocation");
	var screeningLocation = JSON.parse(screeningPath);
	var mcoCode = globalChannelMap.get("mcoCode");
	logger.info("mco code: " + mcoCode);

	var outputFolder = screeningLocation[mcoCode]["dailyFiles"];
	var tempFolder = screeningLocation[mcoCode]["temp"];
	var backupFolder = screeningLocation[mcoCode]["processFiles"];
	var expectedFiles = globalChannelMap.get("fileNames"); // This should be an array
	var errorTypeMap = globalChannelMap.get("errorTypeMap");
	var screeningId = channelMap.get("screeningId");

	var username = configurationMap.get("sftpUserName");
	var password = configurationMap.get("sftpPassword");
	var ip = configurationMap.get("sftpIp");
	var port = configurationMap.get("sftpPort");
	var dbConn;

	var isSuccess = false;

	// Import Java classes

	var File = java.io.File;
	var FileInputStream = java.io.FileInputStream;
	var FileOutputStream = java.io.FileOutputStream;
	var ZipOutputStream = java.util.zip.ZipOutputStream;
	var ZipEntry = java.util.zip.ZipEntry;
	var SimpleDateFormat = java.text.SimpleDateFormat;
	var Date = java.util.Date;
	var Files = java.nio.file.Files;
	var Paths = java.nio.file.Paths;
	var StandardCopyOption = java.nio.file.StandardCopyOption;
	var ArrayList = java.util.ArrayList;
	var HashMap = java.util.HashMap;

	var directory = new File(tempFolder);
	var files = directory.listFiles();
	var availableFilesMap = new java.util.HashMap();
	if (files != null) {
		for (var i = 0; i < files.length; i++) {
			if (files[i].isFile()) {
				var fname = files[i].getName().trim();
				var size = files[i].length();
				if (size > 0) {
					availableFilesMap.put(fname, files[i].getAbsolutePath());
				} else {
					logger.warn("Skipping empty file: " + fname);
				}
			}
		}
	} else {
		logger.error("Directory does not exist or cannot be read: " + tempFolder);
		return;
	}

	// --- Check and Collect Files ---
	var filesToZip = [];
	var allExist = true;
	logger.info("expected files" + expectedFiles)
	for (var fname = 0; fname < expectedFiles.length; fname++) {
		logger.info("logging fname" + expectedFiles[fname]['fileName'])
		var requestedFile = expectedFiles[fname]['fileName'].toString().trim();
		var actualFile = availableFilesMap.get(requestedFile);
		var skipfile=expectedFiles[fname]['skipFile']
		if(skipfile){
			continue;
			}

		if (actualFile == null) {
			logger.warn("Missing or empty file in source: " + requestedFile);
			allExist = false;
		} else {
			filesToZip.push(actualFile); // use actualFile from SFTP list
		}
	}

	if (!allExist) {
		logger.warn("Not all expected files found. Skipping zip.");
		return;
	}

	// --- ZIP Files ---
	var splittedFileName = $('controlFileName').split("_");
	var parts = String(splittedFileName[2]).split(".");
	var dateFormat = parts[0];
	var sdf = new java.text.SimpleDateFormat("yyyyMMdd");
	var todayStr = sdf.format(new java.util.Date());
	var date = dateFormat ? dateFormat : todayStr;
	var zipFileName = mcoCode + "_hrsnob_screenings_" + date + ".zip";
	var zipFilePath = outputFolder + "/" + zipFileName;
	var backupZipPath = backupFolder + "/" + zipFileName;

	var fos = new FileOutputStream(zipFilePath);
	var zos = new ZipOutputStream(fos);

for each (var fullPath in filesToZip) {
	var fileToZip = new File(fullPath);
	var fis = new FileInputStream(fileToZip);
	var entry = new ZipEntry(fileToZip.getName());
	zos.putNextEntry(entry);

	var buffer = java.lang.reflect.Array.newInstance(java.lang.Byte.TYPE, 1024);
	var len;
	while ((len = fis.read(buffer)) > 0) {
		zos.write(buffer, 0, len);
	}
	fis.close();
	zos.closeEntry();
}
	zos.close();
	fos.close();
	logger.info("ZIP created successfully: " + zipFilePath);
	logger.info(backupZipPath)
	Files.copy(
		Paths.get(zipFilePath),
		Paths.get(backupZipPath),
		StandardCopyOption.REPLACE_EXISTING
	);
	logger.info("ZIP copied to backup location: " + backupZipPath);
	isSuccess = true;
	channelMap.put("success", isSuccess);

	// --- Clean up temp files from SFTP ---
	for each (var filePath in filesToZip) {
    var fileToDelete = new File(filePath);

    if (fileToDelete.exists() && fileToDelete.isFile()) {
        org.apache.commons.io.FileUtils.deleteQuietly(fileToDelete);
    } else if (fileToDelete.exists() && fileToDelete.isDirectory()) {
        logger.warn("Skipping deletion, found directory: " + fileToDelete.getAbsolutePath());
    } else {
        logger.warn("File not found for deletion: " + fileToDelete.getAbsolutePath());
    }
}
	if (isSuccess) {
		logger.info("logging completed status in db" + isSuccess )
		var controlFileName = channelMap.get('controlFileName');
		var file;
		try {
			if (!dbConn) {
				dbConn = DatabaseConnectionFactory.createDatabaseConnection(
					jdbdcDriver,
					jbdcUrl,
					dbName,
					dbPassword
				);
			}
				for (var j = 0; j < expectedFiles.length; j++) {
					var file=expectedFiles[j]['fileName']
				var fileResult = dbConn.executeCachedQuery(
					"UPDATE screening_extracts.mco_screening_extracts_details SET status ='COMPLETED', updated_on_utc = NOW() WHERE file_name=? and is_active ='1'  returning *",
					[file]
				);
			}
			file = dbConn.executeCachedQuery(
		        "UPDATE screening_extracts.mco_screening_extracts SET status ='COMPLETED', sent_file_name = ?, updated_on_utc = NOW(), sent_to_mco = NOW() WHERE control_file_name = ? AND is_active = '1' RETURNING *",
		        [ zipFileName.toString(), $('controlFileName') ]
		    );
		}
		catch (err) {
			throw {
				errorType: "POSTGRES ERROR",
				description: "Unable to connect to db",
				rawError: err,
				stackTrace: err.stack,
				msg: err.message
			};
		}
	}
} catch (err) {
	logger.error("Error during zip and clean process: " + err);

	try {
		dbConn = DatabaseConnectionFactory.createDatabaseConnection(
			jdbdcDriver,
			jbdcUrl,
			dbName,
			dbPassword
		);
		var error_type_id = errorTypeMap["MIRTH_INTERNAL_ERROR"];
		var fallbackErrJson = {
			errorType: err.errorType ? err.errorType : "MIRTH INTERNAL ERROR",
			description: "Error While copy or moving" + file,
			stack: err.stack,
			msg: err.msg ? err.msg : err.message,
			rawError: err.rawError ? err.rawError : "SFTP ERROR",
		};
		 var mco_screening_details_id = channelMap.get("screeningDetailsId");

		dbConn.executeCachedQuery(
			"INSERT INTO screening_extracts.mco_screening_extracts_error_logs(mco_screening_id,mco_screening_extracts_details_id,error_json, created_on_utc, updated_on_utc, is_active, screening_error_type_id) VALUES (?, ?::json, NOW(),NOW(),'1',?) returning *",
			[screeningId,mco_screening_details_id,JSON.stringify(fallbackErrJson), error_type_id]
		);
	} catch (logErr) {
		logger.error("Failed to log error to DB: " + logErr);
	}
	throw {
		errorType: "POSTGRES ERROR",
		description: "Unable to connect to db",
		rawError: err,
		stackTrace: err.stack,
		msg: err.message
	};
} finally {

	if (dbConn) dbConn.close();
}

