function checkNamingConvention(fileName) {
  var splittedFileName = fileName.split("_");
  logger.info("logger10" + splittedFileName);
  var controlMco = channelMap.get("mcoCode");

  var validFile = true;

  if (!splittedFileName || splittedFileName.length !== 3) {
    validFile = false;
  } else {
    var mco = splittedFileName[0].toUpperCase();
    var secondPart = splittedFileName[1];
    var thirdPart = splittedFileName[2]; // Expected format: YYYYMMDD.txt

    // Check if MCO code maps to a screening path
    if (mco != controlMco) {
      validFile = false;
    }
    var path = screeningLocation[mco];
    logger.info("path" + path + mco);
    if (!path) {
      validFile = false;
    }
    // Check second part is 'control'
    if (!secondPart) {
      validFile = false;
    } else {
      var fileData;
      fileData = filePart.some(
        (item) => item.toLowerCase() === secondPart.toLowerCase()
      );
      if (!fileData) {
        validFile = false;
      }
    }

    // if (secondPart && !(filePart.includes(secondPart))) {
    //     validFile = false;
    // }

    // Validate third part: YYYYMMDD.txt
    if (thirdPart) {
      var parts = thirdPart.split(".");
      if (parts.length !== 2 || parts[1].toLowerCase() !== "txt") {
        validFile = false;
      } else {
        var datePart = parts[0]; // e.g. 20250708
        if (datePart.length !== 8 || !/^\d{8}$/.test(datePart)) {
          validFile = false;
        }
      }
    } else {
      validFile = false;
    }
  }

  return validFile;
}

function moveFile(file, path) {
  try {
    org.apache.commons.io.FileUtils.copyFile(
      file,
      java.io.File(path),
      false,
      java.nio.file.StandardCopyOption.REPLACE_EXISTING
    );
    return true;
  } catch (err) {
    logger.info("Error While copy or moving" + file + "to" + path + err);
    try {
      if (!dbConn) {
        dbConn = DatabaseConnectionFactory.createDatabaseConnection(
          jdbdcDriver,
          jbdcUrl,
          dbName,
          dbPassword
        );
      }
      var error_type_id = errorTypeMap["SFTP_ERROR"];
      var screening_id = channelMap.get("screeningId");
      var fallbackErrJson = {
        errorType: err.errorType ? err.errorType : "SFTP ERROR",
        description: "Error While copy or moving" + file + "to" + path,
        stack: err.stack,
        msg: err.msg ? err.msg : err.message,
        rawError: err.rawError ? err.rawError : "SFTP ERROR",
      };
      var fileResult = dbConn.executeCachedQuery(
        "INSERT INTO screening_extracts.mco_screening_extracts_error_logs(mco_screening_id, error_json, created_on_utc, updated_on_utc, is_active, screening_error_type_id) VALUES (?, ?::json, NOW(),NOW(),'1',?) returning *",
        [screening_id, JSON.stringify(fallbackErrJson), error_type_id]
      );
    } catch (err) {
      throw err;
    }
    throw error;
  }
}

function copyFile(srcPath, destPath) {
  try {
    var username = configurationMap.get("screeningdlUserName");
    var password = configurationMap.get("screeningdlPassword");
    var ip = configurationMap.get("screeningdlHost");
    var port = configurationMap.get("screeningdlPort");
    var privateKey = configurationMap.get("screeningdlPrivatekey");
    var JSch = Packages.com.jcraft.jsch.JSch;
    var session = null,
      channel = null;

    var JSch = Packages.com.jcraft.jsch.JSch;
    var session = null,
      channel = null;

    var sftpClient = new JSch();
    sftpClient.addIdentity(privateKey);
    session = sftpClient.getSession(username, ip, port);
    session.setPassword(password);

    var config = new java.util.Properties();
    config.put("StrictHostKeyChecking", "no");
    session.setConfig(config);
    session.connect();

    channel = session.openChannel("sftp");
    channel.connect();
    sftp = channel;
    logger.info("========== COPY DEBUG ==========");
	logger.info("src = [" + srcPath + "]");
	logger.info("dst = [" + destPath + "]");
    logger.info("before copying");
    logger.info(srcPath);
    logger.info(destPath);
    var input1 = sftp.get(srcPath);
    var out1 = new java.io.FileOutputStream(destPath);
    org.apache.commons.io.IOUtils.copy(input1, out1);
    input1.close();
    out1.close();
    return true;
  } catch (err) {
    logger.info("Error While copy or moving" + file + "to" + path + err);
    try {
      if (!dbConn) {
        dbConn = DatabaseConnectionFactory.createDatabaseConnection(
          jdbdcDriver,
          jbdcUrl,
          dbName,
          dbPassword
        );
      }
      var error_type_id = errorTypeMap["SFTP_ERROR"];
      var screening_id = channelMap.get("screeningId");
      var fallbackErrJson = {
        errorType: err.errorType ? err.errorType : "SFTP ERROR",
        description: "Error While copy or moving" + file + "to" + path,
        stack: err.stack,
        msg: err.msg ? err.msg : err.message,
        rawError: err.rawError ? err.rawError : "SFTP ERROR",
      };
      var fileResult = dbConn.executeCachedQuery(
        "INSERT INTO screening_extracts.mco_screening_extracts_error_logs(mco_screening_id, error_json, created_on_utc, updated_on_utc, is_active, screening_error_type_id) VALUES (?, ?::json, NOW(),NOW(),'1',?) returning *",
        [screening_id, JSON.stringify(fallbackErrJson), error_type_id]
      );
    } catch (err) {
      throw err;
    }
    throw err;
  }
}
