        : null;
      channelMap.put("screeningDetailsId", mco_screening_details_id);
      fileNameScreeningDetailIdMap[originalFileName] = mco_screening_details_id;
      channelMap.put(
        "fileNameScreeningDetailIdMap",
        fileNameScreeningDetailIdMap
      );
    } else {
      if (!dbConn) {
        dbConn = DatabaseConnectionFactory.createDatabaseConnection(
          jdbdcDriver,
          jbdcUrl,
          dbName,
          dbPassword
        );
      }
      logger.info("logging invalid control file");
      var resourceTypeId = globalChannelMap.get("flatFileResourceId");
      var loggingResult = dbConn.executeCachedQuery(
        "INSERT INTO screening_extracts.mco_screening_extracts( tenant_id, resource_type_id, is_active, created_on_utc, updated_on_utc, status, control_file_name, received_file_size_in_kb) VALUES (?, ?, '1', NOW(),NOW(),'FILTERED', ?, ?)  returning *",
        [mco_id, resourceTypeId, originalFileName, originalFileSize]
      );
      mco_screening_id = loggingResult.next()
        ? loggingResult.getLong("mco_screening_id")
        : null;
      channelMap.put("screeningId", mco_screening_id);
      var loggingDetails = dbConn.executeCachedQuery(
        "INSERT INTO screening_extracts.mco_screening_extracts_details( mco_screening_id,resource_type_id, is_active, file_name, record_count, created_on_utc, updated_on_utc, status)VALUES (?,?,'1', ?, ?,NOW(),NOW(),'FILTERED' )  returning *",
        [mco_screening_id, resourceTypeId, originalFileName, msgObj.length]
      );
      mco_screening_details_id = loggingDetails.next()
        ? loggingDetails.getLong("mco_screening_extracts_details_id")
        : null;
      channelMap.put("screeningDetailsId", mco_screening_details_id);
      fileNameScreeningDetailIdMap[originalFileName] = mco_screening_details_id;
      channelMap.put(
        "fileNameScreeningDetailIdMap",
        fileNameScreeningDetailIdMap
      );
    }

    try {
      var username = configurationMap.get("screeningdlUserName");
      var password = configurationMap.get("screeningdlPassword");
      var ip = configurationMap.get("screeningdlHost");
      var port = configurationMap.get("screeningdlPort");
      var privateKey = configurationMap.get("screeningdlPrivatekey");
      var JSch = Packages.com.jcraft.jsch.JSch;
      var session = null,
        channel = null;

      var JSch = Packages.com.jcraft.jsch.JSch;
      var session = null,
        channel = null;

      var sftpClient = new JSch();
      sftpClient.addIdentity(privateKey);
      session = sftpClient.getSession(username, ip, port);
      session.setPassword(password);
      var config = new java.util.Properties();
      config.put("StrictHostKeyChecking", "no");
      session.setConfig(config);
      session.connect();

      channel = session.openChannel("sftp");
      channel.connect();
      sftp = channel;
      var sourceBase =
        screeningLocation[mco_code] && screeningLocation[mco_code]["inbound"]
          ? screeningLocation[mco_code]["inbound"]
          : generalInbound;
      var destBase1 =
        screeningLocation[mco_code] &&
          screeningLocation[mco_code]["nyecProcessed"]
          ? screeningLocation[mco_code]["nyecProcessed"]
          : generalProcessed; // move destination
      var destBase2 =
        screeningLocation[mco_code] && screeningLocation[mco_code]["rawFolder"];

      var src = sourceBase + "/" + originalFileName;
      logger.info(src);
      var dstMove = destBase1 + "/" + originalFileName;
      logger.info(dstMove);

      if (destBase2) {
        dstCopy = destBase2 + "/" + originalFileName;
        logger.info("invalid control file copy1");
        var isFileCopied = copyFile(src, dstCopy);
        logger.info(originalFileName + "isCopied" + isFileCopied);
      } else {
        var tempDir = new File(generalTemp);

        // Create temp directory if it doesn't exist
        if (!tempDir.exists()) {
          tempDir.mkdirs(); // recursively creates all required directories
        }

        // Build destination file path
        var dstCopy = new File(tempDir, originalFileName);
        // dstCopy = generalTemp + "/" + originalFileName;
        logger.info("invalid control file copy2");
        var isFileCopied = copyFile(src, dstCopy);
        logger.info(originalFileName + "isCopied" + isFileCopied);
      }
      // Move
      if (isFileCopied) {
        if (originalFileSize > 0) {
          logger.info("Attempting to put file to: " + dstMove);
          var file = new Packages.java.io.File(dstCopy);
          // Use the local file path
          var fileToStream = new Packages.java.io.FileInputStream(file);
          // var input1 = sftp.get(src)
          sftp.put(fileToStream, dstMove, sftp.OVERWRITE);
          fileToStream.close();
          logger.info("Moved file to: " + dstMove);
          var attrs = sftp.lstat(src);
          if (!attrs.isDir()) {
            logger.info("Attempting to delete from source : " + src);
            sftp.rm(src);
            logger.info("Deleted file from source: " + src);
          }
          if (!destBase2) {
            logger.info("Before ls stat for invalid control file");
            logger.info(sftp);
            logger.info(dstCopy);
            var attrTemp = dstCopy.exists();
            logger.info("After ls stat for invalid control file");
            logger.info(dstCopy);
            logger.info(attrTemp);
            if (attrTemp) {
              logger.info("inside delete copy ");
              // sftp.rm(dstCopy);
              //  var successFileToBeDeleted = java.io.File(dstCopy)
              org.apache.commons.io.FileUtils.deleteQuietly(file);
              logger.info("Deleted file from source: " + dstCopy);
            }
          }
        } else {
          var remotePath = destBase1 + "/" + originalFileName;
          var filePath = generalInbound + "/" + originalFileName;
          logger.info(filePath);
          var out = sftp.put(remotePath, sftp.OVERWRITE);
          out.close();
          sftp.rm(filePath);
          logger.info("Deleted file: " + filePath);
        }
      }
    } catch (err) {
      logger.info("Error block of invalid control file");
      logger.info(err);
      throw {
        errorType: "MIRTH INTERNAL ERROR",
        description: "Failed In reading control file",
        rawError: err,
        stackTrace: err.stack,
        msg: err.message,
        fileName: originalFileName,
      };
    }
  } catch (err) {
    throw {
      errorType: "MIRTH INTERNAL ERROR",
      description: "Failed In reading control file",
      rawError: err,
      stackTrace: err.stack,
      msg: err.message,
      fileName: originalFileName,
    };
  }
}

